"""Copy every payout from the Tallyline Payouts API into payouts.jsonl."""
import argparse
import json
import time
import urllib.error
import urllib.parse
import urllib.request


MAX_ATTEMPTS = 10


class InvalidCursor(Exception):
    """The export cursor was rejected; the export must start over."""


def _get_window(base_url, cursor, limit):
    params = {"limit": limit}
    if cursor is not None:
        params["cursor"] = cursor
    url = f"{base_url}/v2/payouts?{urllib.parse.urlencode(params)}"

    for attempt in range(MAX_ATTEMPTS):
        try:
            with urllib.request.urlopen(url, timeout=30) as resp:
                return json.load(resp)
        except urllib.error.HTTPError as exc:
            if exc.code == 429:
                retry_after = exc.headers.get("Retry-After", "1")
                try:
                    delay = max(0.0, float(retry_after))
                except (TypeError, ValueError):
                    delay = 1.0
                time.sleep(delay)
                continue
            if exc.code == 400:
                try:
                    body = json.load(exc)
                except (ValueError, OSError):
                    body = {}
                if body.get("error") == "invalid_cursor":
                    raise InvalidCursor() from exc
            raise
    raise RuntimeError(f"still rate limited after {MAX_ATTEMPTS} attempts")


def fetch_payouts(base_url):
    """Export every payout once, following cursors until the export drains."""
    seen = set()
    ordered = []
    cursor = None
    restarts = 0

    while True:
        try:
            window = _get_window(base_url, cursor, limit=1000)
        except InvalidCursor:
            restarts += 1
            if restarts > 3:
                raise
            # The cursor is unusable. Start the export again from the beginning.
            seen.clear()
            ordered.clear()
            cursor = None
            continue

        for payout in window["payouts"]:
            payout_id = payout["id"]
            if payout_id not in seen:
                seen.add(payout_id)
                ordered.append(payout)

        cursor = window["cursor"]
        if window["drained"]:
            return ordered


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--base-url", required=True)
    ap.add_argument("--out", default="payouts.jsonl")
    args = ap.parse_args()
    payouts = fetch_payouts(args.base_url.rstrip("/"))
    with open(args.out, "w") as f:
        for p in payouts:
            f.write(json.dumps(p) + "\n")
    print(f"synced {len(payouts)} payouts")


if __name__ == "__main__":
    main()

